#menu { inset: 0; margin: auto; width: min(310px, 90vw); height: fit-content; box-sizing: border-box; border: 1px solid #46534e; border-radius: 12px; padding: 20px; background: #202925; font: 16px system-ui,sans-serif; box-shadow: 0 14px 54px #0004; }
#menu::backdrop { background: #16201d66; }
#menu > span { margin: 0 0 16px; }
#menu button { background: #34403a; color: white; border: 0; border-radius: 6px; padding: 6px 12px 12px; font: inherit; cursor: pointer; }
#menu button:hover { background: #47564e; }
#menu button:not(#close-menu) { width: 46%; }
#menu #close-menu { background: transparent; width: 44px; height: 44px; padding: 0; right: 2px; top: 0; font-size: 22px; }
@media screen {
 body { height: 100vh; height: 100dvh; display: flex; flex-direction: column; overflow: hidden; background: #e4e8e4; }
 #navbar { position: relative; order: -1; flex: none; height: auto; background: #17211d; box-shadow: none; }
 #navcontent { display: flex; align-items: center; gap: 4px; padding: 10px 22px; }
 #navbar #logo { display: block; margin-right: auto; text-decoration: none; }
 #title { padding: 0; margin: 0; color: #f7faf7 !important; font: bold 23px/44px monospace; letter-spacing: -.065em; }
 #title::first-letter { color: #a5d5b7; }
 #navbar .navbutton { display: inline-flex; align-items: center; justify-content: center; gap: 6px; float: none; min-height: 44px; margin: 0 !important; padding: 0 11px; background: transparent; color: #e4eae6; border: 0; border-radius: 5px; font: 600 14px system-ui,sans-serif; }
 #navbar .material-icons { font-size: 19px; }
 #navbar .navbutton:hover { background: #354039; }
 #navbar .selected { background: #33483c; color: #c1ebcb; }
 #navbar #readbutton { border: 1px solid #65776b; }
 button:focus-visible, a:focus-visible { outline: 2px solid #8acda5; outline-offset: 1px; }
 .workspace { flex: 1; min-height: 0; display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); }
 .workspace section { display: flex; min-height: 0; min-width: 0; flex-direction: column; }
 .source-pane { border-right: 1px solid #cbd3cd; }
 .pane-label { flex: none; padding: 14px 32px; border-bottom: 1px solid #d8dfd9; background: #eff3ef; color: #415549; font: 600 12px/16px monospace; letter-spacing: .075em; text-transform: uppercase; }
 .preview-pane .pane-label { background: #f8faf7; }
 #in, #out, #out.focused { position: relative; inset: auto; flex: 1; width: auto; min-height: 0; margin: 0; border: 0; box-shadow: none; z-index: auto; }
 #in { font-size: 16px; overflow: hidden; }
 .CodeMirror-scroll { padding: 0; }
 .CodeMirror-lines { padding: 26px 0; }
 .CodeMirror pre { padding: 0 32px; line-height: 1.65; }
 #in .CodeMirror { background: #f6f7f4; }
 .cm-header-1 { font-size: 1.55em; }
 .cm-header-2 { font-size: 1.32em; }
 #out { padding: 26px 36px 64px; line-height: 1.65; overflow-wrap: anywhere; }
 #out h1, #out h2 { font-family: Georgia,serif; color: #23372c; }
 #out a { color: #21664c; }
 #out table { max-width: 100%; overflow-x: auto; }
 .reading .workspace, .view .workspace { grid-template-columns: minmax(0,840px); justify-content: center; }
 .reading .source-pane, .view .source-pane { display: none; }
 .nightmode { background: #181c19; }
 .nightmode .pane-label { background: #202823; color: #c3d2c6; border-color: #3c453e; }
}
@media screen and (max-width: 1060px) {
 #navcontent { display: grid; grid-template-columns: repeat(6,minmax(0,1fr)); gap: 4px; padding: 6px 10px; }
 #navbar #logo { grid-column: 1 / 5; }
 #navbar #readbutton { grid-column: 5 / 7; grid-row: 1; }
 #navbar .navbutton:not(#readbutton) { flex-direction: column; gap: 2px; padding: 3px 0; font-size: 12px; }
 #title { font-size: 20px; }
}
@media screen and (max-width: 720px) {
 .workspace { grid-template-columns: minmax(0,1fr); }
 .workspace .preview-pane { display: none; }
 .reading .preview-pane, .view .preview-pane { display: flex; }
 .source-pane { border: 0; }
 .pane-label { padding: 10px 18px; }
 .CodeMirror-lines { padding: 18px 0; }
 .CodeMirror pre { padding: 0 18px; }
 #out { padding: 18px 20px 48px; }
}
